import 'package:flutter/material.dart';
import '../../core/database/app_database.dart';
class PharmacyPage extends StatefulWidget{const PharmacyPage({super.key});@override State<PharmacyPage> createState()=>_PharmacyPageState();}
class _PharmacyPageState extends State<PharmacyPage>{List<Map<String,Object?>> rows=const[];bool loading=true;
 Future<void> load()async{final db=await AppDatabase.instance.database;final x=await db.rawQuery("SELECT * FROM products WHERE category='Pharmacy' OR expiry_date IS NOT NULL ORDER BY name");if(mounted)setState((){rows=x;loading=false;});}
 @override void initState(){super.initState();load();}
 Future<void> add()async{final n=TextEditingController(),batch=TextEditingController(),expiry=TextEditingController(),price=TextEditingController(),stock=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(context)=>AlertDialog(title:const Text('Add Medicine'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Medicine name')),const SizedBox(height:8),TextField(controller:batch,decoration:const InputDecoration(labelText:'Batch no.')),const SizedBox(height:8),TextField(controller:expiry,decoration:const InputDecoration(labelText:'Expiry YYYY-MM-DD')),const SizedBox(height:8),TextField(controller:price,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Sale price')),const SizedBox(height:8),TextField(controller:stock,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Stock'))])),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Save'))]));if(ok!=true||n.text.trim().isEmpty)return;await AppDatabase.instance.saveMedicine(id:DateTime.now().microsecondsSinceEpoch.toString(),name:n.text,batchNo:batch.text,expiryDate:expiry.text,price:double.tryParse(price.text)??0,stock:double.tryParse(stock.text)??0);await load();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Pharmacy')),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:const Text('Add Medicine')),body:loading?const Center(child:CircularProgressIndicator()):rows.isEmpty?const Center(child:Text('No medicines yet.')):ListView.separated(itemCount:rows.length,separatorBuilder:(_,__)=>const Divider(height:1),itemBuilder:(_,i){final x=rows[i];return ListTile(leading:const CircleAvatar(child:Icon(Icons.medication)),title:Text(x['name'].toString()),subtitle:Text('Batch '+(x['batch_no']??'-').toString()+' • Expiry '+(x['expiry_date']??'-').toString()+' • Stock '+x['stock'].toString()),trailing:Text(x['price'].toString()));}));}
